{"graphInstanceObjectId":"6114dbdf-2c98-4684-8314-bcd1d2dd8af0","graphInstanceFolderObjectId":"33c8bc67-ef39-4ee1-9049-d38e9d32e75e","queries":[{"displayName":"QS_CivicSignal_Graph_Validation","id":"b503b493-4bad-4a18-a969-9e8e652f4af7","queryMode":"GQLCode","gqlQueryText":"// 01_Opportunity_Count
MATCH (n:Opportunity)
RETURN count(n) AS opportunity_count

// 02_Buyer_Count
MATCH (n:Buyer)
RETURN count(n) AS buyer_count

// 03_Source_Count
MATCH (n:Source)
RETURN count(n) AS source_count

// 04_Category_Count
MATCH (n:ProcurementCategory)
RETURN count(n) AS category_count

// 05_Publishes_Edges
MATCH (:Buyer)-[:publishes]->(:Opportunity)
RETURN count(*) AS publishes_edges

// 06_ListedBy_Edges
MATCH (:Opportunity)-[:listedBy]->(:Source)
RETURN count(*) AS listed_by_edges

// 07_ClassifiedAs_Edges
MATCH (:Opportunity)-[:classifiedAs]->(:ProcurementCategory)
RETURN count(*) AS classified_as_edges

// 08_Complete_Procurement_Path
MATCH (b:Buyer)-[:publishes]->(o:Opportunity),
      (o)-[:listedBy]->(s:Source),
      (o)-[:classifiedAs]->(c:ProcurementCategory)
RETURN count(*) AS complete_paths

// 09_Sample_Traversal
MATCH (b:Buyer)-[:publishes]->(o:Opportunity),
      (o)-[:listedBy]->(s:Source),
      (o)-[:classifiedAs]->(c:ProcurementCategory)
RETURN b, o, s, c
LIMIT 5


// 10_Unclassified_Opportunities
MATCH (o:Opportunity)
WHERE NOT EXISTS {
    MATCH (o)-[:classifiedAs]->(:ProcurementCategory)
}
RETURN count(o) AS unclassified_opportunities

// 11_Total_Connected_Opportunity_Paths
MATCH (:Buyer)-[:publishes]->(o:Opportunity)-[:listedBy]->(:Source)
RETURN count(DISTINCT o) AS connected_opportunities

","nodes":[],"edges":[]}]}
